import 'package:flutter/material.dart'; import '../../data/models/team.dart'; class TeamLogo extends StatelessWidget{const TeamLogo({super.key,required this.team,this.radius=36});final Team team;final double radius;@override Widget build(BuildContext context)=>CircleAvatar(radius:radius,backgroundColor:Theme.of(context).colorScheme.primaryContainer,backgroundImage:team.logoUrl.isNotEmpty?NetworkImage(team.logoUrl):null,onBackgroundImageError:team.logoUrl.isNotEmpty?(_,__){}:null,child:team.logoUrl.isEmpty?Icon(Icons.sports_soccer,size:radius,color:Theme.of(context).colorScheme.primary):null);}